			ln := len(o.R.TBPEntidades)
			if ln > 1 && i < ln-1 {
				o.R.TBPEntidades[i] = o.R.TBPEntidades[ln-1]
			}
			o.R.TBPEntidades = o.R.TBPEntidades[:ln-1]
